"use client";

import { useState, useEffect, Suspense } from "react";
import Link from "next/link";
import Image from "next/image";
import { Search, LogOut, Menu, X, User } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { useAuthStore } from "@/store/useAuthStore";
import { useFavoritesStore } from "@/store/useFavoritesStore";
import { useRouter, useSearchParams, usePathname } from "next/navigation";
import { registerInteraction } from "@/lib/interactions";
import { MessagesDropdown } from "@/components/chat/MessagesDropdown";
import { useChatStore } from "@/store/useChatStore";
import NotificationsBadge from "@/components/notifications/NotificationsBadge";
import { CartBadge } from "@/components/cart/CartBadge";

function SearchBar() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const [query, setQuery] = useState(() => searchParams.get("search") || searchParams.get("q") || "");

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    if (query.trim()) {
      const trimmedQuery = query.trim();
      registerInteraction({
        search_term: trimmedQuery,
        interaction_type: 'search'
      });
      router.push(`/?search=${encodeURIComponent(trimmedQuery)}#recommendations-section`);
      window.setTimeout(() => {
        document.getElementById("recommendations-section")?.scrollIntoView({
          behavior: "smooth",
          block: "start",
        });
      }, 100);
    } else {
      router.push("/");
    }
  };

  return (
    <form onSubmit={handleSearch} className="relative flex w-full min-w-0 items-center xl:w-80 2xl:w-[400px]">
      <input
        type="text"
        placeholder="Buscar"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        className="h-11 w-full rounded-full border-2 border-white bg-transparent pl-5 pr-11 text-sm font-medium text-white placeholder:text-white/80 transition-all focus:outline-none focus:ring-1 focus:ring-white"
      />
      <button type="submit" aria-label="Buscar" className="absolute right-0 top-1/2 flex h-11 w-11 -translate-y-1/2 items-center justify-center text-white transition-colors hover:text-[#7ed957]">
        <Search size={20} strokeWidth={2.5} />
      </button>
    </form>
  );
}

export function Header() {
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const { isAuthenticated, user, logout } = useAuthStore();
  const { fetchFavorites } = useFavoritesStore();
  const { connectSocket, disconnectSocket, fetchConversations } = useChatStore();
  const pathname = usePathname();
  const router = useRouter();

  useEffect(() => {
    if (isAuthenticated && user?.id) {
      fetchFavorites();
      fetchConversations();
      
      const interval = setInterval(() => {
          fetchConversations();
      }, 60000);
      return () => clearInterval(interval);
    } else {
      disconnectSocket();
    }
  }, [isAuthenticated, user?.id]);

  // Close mobile menu on route change
  useEffect(() => {
    setIsMobileMenuOpen(false);
  }, [pathname]);

  return (
    <header className="fixed top-0 left-0 right-0 z-[45] flex flex-col font-sans">
      {/* Main Header */}
      <div className="bg-primary text-white shadow-md transition-all duration-300">
        <div className="container mx-auto flex h-20 min-w-0 items-center justify-between gap-3 px-4 xl:h-24">
          
          {/* Left Side: Logo + Nav */}
          <div className="flex min-w-0 items-center gap-8 2xl:gap-16">
            {/* Logo */}
            <Link href="/" aria-label="Drooopy - Inicio" className="group flex shrink-0 items-center gap-2">
               <div className="relative h-14 w-40 sm:w-48 xl:h-20 xl:w-[200px]">
                 <Image 
                   src="/logo-drooopy.svg" 
                   alt="Drooopy" 
                   fill
                   className="object-contain object-left"
                   priority
                 />
               </div>
            </Link>

            {/* Desktop Navigation */}
            <nav className="hidden items-center gap-6 text-base font-medium font-[family-name:var(--font-varela-round)] xl:flex 2xl:gap-8">
              <Link href="/" className="hover:text-[#7ed957] transition-colors text-white">
                Inicio
              </Link>
              <Link href="/nosotros" className="hover:text-[#7ed957] transition-colors text-white">
                Nosotros
              </Link>
              <Link href="/contacto" className="hover:text-[#7ed957] transition-colors text-white">
                Contacto
              </Link>
              <Link href="/sell" className="hover:text-[#7ed957] transition-colors text-white">
                Vender
              </Link>
            </nav>
          </div>

          {/* Right Side: Search + Actions */}
          <div className="flex min-w-0 shrink-0 items-center gap-4 xl:gap-6">
            {/* Search Bar (Desktop) */}
            <div className="hidden xl:block">
              <Suspense fallback={<div className="w-64 h-10 bg-primary/50 border border-white/30 rounded-full" />}>
                <SearchBar />
              </Suspense>
            </div>

            {/* Actions */}
            <div className="flex items-center gap-1 xl:gap-4">
              {isAuthenticated && (
                <div className="hidden items-center gap-4 xl:flex">
                  <MessagesDropdown />
                </div>
              )}
              {isAuthenticated && <NotificationsBadge />}
              <div className="hidden items-center gap-4 xl:flex">
                <CartBadge />

                <div
                  className="relative"
                  onMouseEnter={() => setIsUserMenuOpen(true)}
                  onMouseLeave={() => setIsUserMenuOpen(false)}
                >
                  {isAuthenticated ? (
                    <button className="flex items-center justify-center w-10 h-10 rounded-full text-white hover:text-[#7ed957] transition-all">
                      {user?.name ? (
                        <span className="font-bold text-lg">{user.name.charAt(0).toUpperCase()}</span>
                      ) : (
                        <i className="fa-solid fa-circle-user text-[28px]" />
                      )}
                    </button>
                  ) : (
                    <Link href="/login" className="flex items-center justify-center w-10 h-10 rounded-full text-white hover:text-[#7ed957] transition-all">
                      <i className="fa-solid fa-circle-user text-[28px]" />
                    </Link>
                  )}

                  <AnimatePresence>
                    {isUserMenuOpen && isAuthenticated && (
                      <motion.div
                        initial={{ opacity: 0, y: 10 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: 10 }}
                        transition={{ duration: 0.2 }}
                        className="absolute right-0 top-full mt-2 w-64 bg-white text-black rounded-xl shadow-xl border border-gray-100 overflow-hidden py-2"
                      >
                        <div className="px-4 py-3 border-b border-gray-100 bg-gray-50">
                          <p className="font-semibold text-sm text-primary">Hola, {user?.name}</p>
                        </div>
                        <nav className="flex flex-col">
                          {(user?.role === "admin" || user?.role === "supplier" || user?.role === "seller") && (
                            <Link href="/admin/dashboard" className="px-4 py-2 text-sm hover:bg-gray-50 flex items-center gap-3 font-medium text-gray-700 hover:text-primary">
                              <span>🛡️</span> {user.role === "supplier" ? "Mi Empresa" : "Panel Admin"}
                            </Link>
                          )}
                          {user?.role === "admin" && (
                            <>
                              <Link href="/client/orders" className="px-4 py-2 text-sm hover:bg-gray-50 flex items-center gap-3 font-medium text-gray-700 hover:text-primary">
                                <span>📦</span> Mis Pedidos
                              </Link>
                              <Link href="/cart" className="px-4 py-2 text-sm hover:bg-gray-50 flex items-center gap-3 font-medium text-gray-700 hover:text-primary">
                                <span>🛒</span> Mi Carrito
                              </Link>
                            </>
                          )}
                          {user?.role === "client" ? (
                            <Link href="/client/profile" className="px-4 py-2 text-sm hover:bg-gray-50 flex items-center gap-3 font-medium text-gray-700 hover:text-primary">
                              <User size={16} /> Mi cuenta
                            </Link>
                          ) : (
                            <Link href="/client/favorites" className="px-4 py-2 text-sm hover:bg-gray-50 flex items-center gap-3 text-gray-700 hover:text-primary">
                              <span>❤️</span> Favoritos
                            </Link>
                          )}
                          <div className="h-px bg-gray-100 my-1" />
                          <button
                            onClick={() => {
                              logout();
                              router.push("/login");
                            }}
                            className="w-full text-left px-4 py-2 text-sm hover:bg-red-50 flex items-center gap-3 text-red-500"
                          >
                            <LogOut size={16} /> Cerrar Sesión
                          </button>
                        </nav>
                      </motion.div>
                    )}
                  </AnimatePresence>
                </div>
              </div>

              {/* Mobile Actions */}
              <div className="flex items-center gap-1 xl:hidden">
                <CartBadge />
                <button
                  type="button"
                  aria-label={isMobileMenuOpen ? "Cerrar menú" : "Abrir menú"}
                  aria-expanded={isMobileMenuOpen}
                  aria-controls="header-mobile-menu"
                  className="flex h-11 w-11 items-center justify-center text-white transition-colors hover:text-[#7ed957]"
                  onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
                >
                  {isMobileMenuOpen ? <X size={28} /> : <Menu size={28} />}
                </button>
              </div>
            </div>
          </div>
        </div>

        {/* Mobile Navigation Menu */}
        <AnimatePresence>
            {isMobileMenuOpen && (
                <motion.div
                    initial={{ height: 0, opacity: 0 }}
                    animate={{ height: "auto", opacity: 1 }}
                    exit={{ height: 0, opacity: 0 }}
                    id="header-mobile-menu"
                    className="overflow-hidden border-t border-white/10 bg-primary xl:hidden"
                >
                    <div className="flex max-h-[calc(100dvh-5rem)] flex-col gap-4 overflow-y-auto p-4">
                        <div className="pb-4 border-b border-white/10">
                            <Suspense fallback={<div className="w-full h-10 bg-primary/50 rounded-full" />}>
                                <SearchBar />
                            </Suspense>
                        </div>
                        <nav className="flex flex-col gap-2 [&_a]:min-h-11 [&_a]:content-center">
                            <Link href="/" className="py-2 px-4 hover:bg-white/10 rounded-lg transition-colors">Inicio</Link>
                            <Link href="/nosotros" className="py-2 px-4 hover:bg-white/10 rounded-lg transition-colors">Nosotros</Link>
                            <Link href="/contacto" className="py-2 px-4 hover:bg-white/10 rounded-lg transition-colors">Contacto</Link>
                            <Link href="/sell" className="py-2 px-4 hover:bg-white/10 rounded-lg transition-colors">Vender en Drooopy</Link>
                            {isAuthenticated ? (
                              <>
                                {(user?.role === "admin" || user?.role === "supplier" || user?.role === "seller") && (
                                  <Link href="/admin/dashboard" className="py-2 px-4 hover:bg-white/10 rounded-lg transition-colors flex items-center gap-3">
                                    <span>🛡️</span> {user.role === "supplier" ? "Mi Empresa" : "Panel Admin"}
                                  </Link>
                                )}
                                {user?.role !== "client" && (
                                  <>
                                    <Link href="/client/favorites" className="py-2 px-4 hover:bg-white/10 rounded-lg transition-colors flex items-center gap-3">
                                      <span>❤️</span> Favoritos
                                    </Link>
                                    <Link href="/admin/messages" className="py-2 px-4 hover:bg-white/10 rounded-lg transition-colors flex items-center gap-3">
                                      <span>✉️</span> Mensajes
                                    </Link>
                                  </>
                                )}
                                {user?.role === "admin" && (
                                  <>
                                    <Link href="/client/orders" className="py-2 px-4 hover:bg-white/10 rounded-lg transition-colors flex items-center gap-3">
                                      <span>📦</span> Mis Pedidos
                                    </Link>
                                    <Link href="/cart" className="py-2 px-4 hover:bg-white/10 rounded-lg transition-colors flex items-center gap-3">
                                      <span>🛒</span> Mi Carrito
                                    </Link>
                                  </>
                                )}
                                <div className="h-px bg-white/10 my-1" />
                                <Link
                                  href={user?.role === "client" ? "/client/profile" : "/admin/profile"}
                                  className="py-2 px-4 hover:bg-white/10 rounded-lg transition-colors flex items-center gap-3"
                                >
                                  <User size={18} /> Mi cuenta
                                </Link>
                                <button
                                  onClick={() => {
                                    logout();
                                    router.push("/login");
                                  }}
                                  className="py-2 px-4 hover:bg-red-500/20 rounded-lg transition-colors flex items-center gap-3 text-red-300 text-left w-full"
                                >
                                  <LogOut size={18} /> Cerrar Sesión
                                </button>
                              </>
                            ) : (
                              <Link href="/login" className="py-2 px-4 hover:bg-white/10 rounded-lg transition-colors">
                                Iniciar sesión
                              </Link>
                            )}
                        </nav>
                    </div>
                </motion.div>
            )}
        </AnimatePresence>
      </div>
    </header>
  );
}
